import {emptyState,type FinanceState,type Transaction} from '../../lib/finance.ts';import {impliedRate} from '../../lib/fx.ts';
export const repairState=():FinanceState=>({...structuredClone(emptyState),profile:{ownerId:'one',name:'Investment transfer repair',currency:'USD',revision:1},accounts:[{id:'source',ownerId:'one',name:'Source investment',type:'investment',currency:'USD',openingBalance:1000000,openingDate:'2026-01-01',archived:0},{id:'destination',ownerId:'one',name:'Destination crypto',type:'crypto',currency:'USD',openingBalance:0,openingDate:'2026-01-01',archived:0}],categories:[{id:'purpose',ownerId:'one',name:'Investment Contributions',color:'#0d9488',parentId:null}]});
export function addRepairPair(s:FinanceState,id='pair',amount=10000,patch:{fromId?:string;toId?:string;outKind?:Transaction['kind'];inKind?:Transaction['kind'];date?:string;destinationDate?:string;toAmount?:number;status?:'pending'|'confirmed'}={}){
 const from=s.accounts.find(a=>a.id===(patch.fromId??'source'))!,to=s.accounts.find(a=>a.id===(patch.toId??'destination'))!,date=patch.date??'2026-02-01',destinationDate=patch.destinationDate??'2026-02-03',toAmount=patch.toAmount??amount,quote=impliedRate(amount,from.currency,toAmount,to.currency);
 const out:Transaction={id:id+'-out',ownerId:'one',accountId:from.id,categoryId:s.categories[0]?.id??null,date,name:id+' original debit',amount:-amount,kind:patch.outKind??'investment_contribution',transferId:id,notes:'Original debit notes',importKey:id+'-csv-debit',lockedFields:['name']},into:Transaction={...out,id:id+'-in',accountId:to.id,date:destinationDate,name:id+' original deposit',amount:toAmount,kind:patch.inKind??'investment_contribution',notes:'Original credit notes',importKey:id+'-csv-credit',lockedFields:['tagIds']};
 s.transactions.push(out,into);s.transferDetails.push({id,ownerId:'one',status:patch.status??'confirmed',date,destinationDate,fromCurrency:from.currency,toCurrency:to.currency,fromAmount:amount,toAmount,rateNumerator:String(quote.numerator),rateDenominator:String(quote.denominator),rateDate:from.currency===to.currency?null:date,rateSource:from.currency===to.currency?'identity':'manual',sourceFee:0,destinationFee:0,requestId:null,requestFingerprint:null,createdAt:'2026-02-05T00:00:00.000Z',updatedAt:'2026-02-06T00:00:00.000Z'});return {out,into};
}
